Código
X = model.matrix(Cases ~ 0+City + Age, data = danishlc)
attr(X,"assign") = attr(X,"contrasts") = NULL

data_GLM2 =
  list(
    n = nrow(X),
    p = ncol(X),
    X = X,
    Y = danishlc$Cases,
    offset = danishlc$Pop
  )

mod_GLM2 = stan_model(model_name = "GLM2", model_code = "
data {
  int&lt;lower=1&gt; n;
  int&lt;lower=1&gt; p;
  matrix[n, p] X;
  int&lt;lower=0&gt; Y[n];
  vector[n] offset;
}
parameters {
  vector[p] beta;
}
transformed parameters {
  vector[n] eta;
  eta = X * beta;
}
model {
  for (i in 1:n) {
    Y[i] ~ poisson(offset[i] + exp(eta[i]));
  }
  for (k in 1:p) {
    beta[k] ~ normal(0,10);
  }
}
generated quantities {
  real Horsens_vs_Kolding;
  real Horsens_vs_Vejle;
  real Kolding_vs_Vejle;

  Horsens_vs_Kolding = beta[1] - beta[2];
  Horsens_vs_Vejle   = beta[1] - beta[3];
  Kolding_vs_Vejle   = beta[2] - beta[3];
}

")



fit_GLM2 = rstan::sampling(mod_GLM2, data = data_GLM2)


plot(fit_GLM2, pars = "beta", ci_level = 0.95)
